//! Reader for the grouped, vertex-colored GLB generated by tools/about/export_kitchen.py.
//! The production renderer needs no JavaScript scene library or general-purpose glTF runtime.
use serde_json::Value;
pub struct KitchenMesh {
    pub vertices: Vec<f32>,
    pub parts: Vec<KitchenPart>,
}
#[derive(Clone)]
pub struct KitchenPart {
    pub first: usize,
    pub count: usize,
    pub name: String,
    pub pivot: [f32; 3],
    pub offset: [f32; 3],
    pub start: f32,
    pub end: f32,
    pub texture: usize,
}
fn invalid() -> String {
    "Invalid kitchen model".into()
}
fn word(bytes: &[u8], at: usize) -> Result<u32, String> {
    Ok(u32::from_le_bytes(
        bytes
            .get(at..at + 4)
            .ok_or_else(invalid)?
            .try_into()
            .map_err(|_| invalid())?,
    ))
}
fn number(v: &Value, key: &str) -> Result<usize, String> {
    v[key].as_u64().map(|n| n as usize).ok_or_else(invalid)
}
fn view<'a>(doc: &Value, data: &'a [u8], index: usize) -> Result<&'a [u8], String> {
    let v = &doc["bufferViews"][index];
    if v["buffer"].as_u64() != Some(0) {
        return Err(invalid());
    }
    let start = v["byteOffset"].as_u64().unwrap_or(0) as usize;
    let len = number(v, "byteLength")?;
    data.get(start..start.checked_add(len).ok_or_else(invalid)?)
        .ok_or_else(invalid)
}
fn floats(doc: &Value, data: &[u8], index: usize, width: usize) -> Result<Vec<f32>, String> {
    let a = &doc["accessors"][index];
    if a["type"].as_str()
        != Some(if width == 2 {
            "VEC2"
        } else if width == 4 {
            "VEC4"
        } else {
            "VEC3"
        })
    {
        return Err(invalid());
    }
    let component = a["componentType"].as_u64().ok_or_else(invalid)?;
    let component_size = match component {
        5126 => 4,
        5122 | 5123 => 2,
        5121 => 1,
        _ => return Err(invalid()),
    };
    let count = number(a, "count")?;
    if count > 300_000 {
        return Err(invalid());
    }
    let vi = number(a, "bufferView")?;
    let bytes = view(doc, data, vi)?;
    let offset = a["byteOffset"].as_u64().unwrap_or(0) as usize;
    let stride = doc["bufferViews"][vi]["byteStride"]
        .as_u64()
        .unwrap_or((width * component_size) as u64) as usize;
    let mut out = Vec::with_capacity(count * width);
    for i in 0..count {
        for j in 0..width {
            let at = offset + i * stride + j * component_size;
            let v = match component {
                5121 => *bytes.get(at).ok_or_else(invalid)? as f32 / 255.,
                5126 => f32::from_bits(word(bytes, at)?),
                5123 => {
                    u16::from_le_bytes(
                        bytes
                            .get(at..at + 2)
                            .ok_or_else(invalid)?
                            .try_into()
                            .map_err(|_| invalid())?,
                    ) as f32
                        / 65535.
                }
                _ => (i16::from_le_bytes(
                    bytes
                        .get(at..at + 2)
                        .ok_or_else(invalid)?
                        .try_into()
                        .map_err(|_| invalid())?,
                ) as f32
                    / 32767.)
                    .max(-1.),
            };
            if !v.is_finite() {
                return Err(invalid());
            }
            out.push(v);
        }
    }
    Ok(out)
}
pub fn decode(bytes: &[u8]) -> Result<KitchenMesh, String> {
    if bytes.get(0..4) != Some(b"glTF")
        || word(bytes, 4)? != 2
        || word(bytes, 8)? as usize != bytes.len()
    {
        return Err(invalid());
    }
    let json_len = word(bytes, 12)? as usize;
    if word(bytes, 16)? != 0x4e4f534a {
        return Err(invalid());
    }
    let end = 20_usize.checked_add(json_len).ok_or_else(invalid)?;
    let doc: Value =
        serde_json::from_slice(bytes.get(20..end).ok_or_else(invalid)?).map_err(|_| invalid())?;
    let bin_len = word(bytes, end)? as usize;
    if word(bytes, end + 4)? != 0x004e4942 {
        return Err(invalid());
    }
    let data = bytes.get(end + 8..end + 8 + bin_len).ok_or_else(invalid)?;
    if doc["meshes"].as_array().map(Vec::len) != Some(1)
        || !doc["meshes"][0]["primitives"]
            .as_array()
            .is_some_and(|p| !p.is_empty() && p.len() <= 20)
    {
        return Err(invalid());
    }
    let mut vertices = Vec::new();
    let mut parts = Vec::new();
    for p in doc["meshes"][0]["primitives"]
        .as_array()
        .ok_or_else(invalid)?
    {
        let first = vertices.len() / 12;
        if p["mode"].as_u64().unwrap_or(4) != 4 {
            return Err(invalid());
        }
        let attr = &p["attributes"];
        let mut pos = floats(&doc, data, number(attr, "POSITION")?, 3)?;
        let node = &doc["nodes"][0];
        if node["rotation"].is_array() || node["matrix"].is_array() {
            return Err(invalid());
        }
        for (i, v) in pos.iter_mut().enumerate() {
            *v = *v * node["scale"][i % 3].as_f64().unwrap_or(1.) as f32
                + node["translation"][i % 3].as_f64().unwrap_or(0.) as f32;
        }
        let normals = floats(&doc, data, number(attr, "NORMAL")?, 3)?;
        let color_index = number(attr, "COLOR_0")?;
        let color_width = if doc["accessors"][color_index]["type"].as_str() == Some("VEC3") {
            3
        } else {
            4
        };
        let colors = floats(&doc, data, color_index, color_width)?;
        if normals.len() != pos.len() || colors.len() * 3 != pos.len() * color_width {
            return Err(invalid());
        }
        let a = &doc["accessors"][number(p, "indices")?];
        let count = number(a, "count")?;
        if count > 600_000 || count % 3 != 0 || vertices.len() / 12 + count > 600_000 {
            return Err(invalid());
        }
        let vi = number(a, "bufferView")?;
        let ix = view(&doc, data, vi)?;
        let offset = a["byteOffset"].as_u64().unwrap_or(0) as usize;
        let size = match a["componentType"].as_u64() {
            Some(5123) => 2,
            Some(5125) => 4,
            _ => return Err(invalid()),
        };
        let uv = attr["TEXCOORD_0"]
            .as_u64()
            .map(|i| floats(&doc, data, i as usize, 2))
            .transpose()?;
        vertices.reserve(count * 12);
        for k in 0..count {
            let at = offset + k * size;
            let i = if size == 4 {
                word(ix, at)? as usize
            } else {
                u16::from_le_bytes(
                    ix.get(at..at + 2)
                        .ok_or_else(invalid)?
                        .try_into()
                        .map_err(|_| invalid())?,
                ) as usize
            };
            vertices.extend_from_slice(pos.get(i * 3..i * 3 + 3).ok_or_else(invalid)?);
            vertices.extend_from_slice(normals.get(i * 3..i * 3 + 3).ok_or_else(invalid)?);
            vertices.extend_from_slice(if let Some(uv) = &uv {
                uv.get(i * 2..i * 2 + 2).ok_or_else(invalid)?
            } else {
                &[0., 0.]
            });
            // glTF COLOR_0 values are linear, including normalized integer attributes.
            // Keep them linear for lighting; the fragment shader applies the display transfer.
            vertices.extend_from_slice(
                colors
                    .get(i * color_width..i * color_width + 3)
                    .ok_or_else(invalid)?,
            );
            vertices.push(1.);
        }
        let meta =
            &doc["materials"][p["material"].as_u64().unwrap_or(0) as usize]["extras"]["assembly"];
        if meta.is_object() {
            let vector = |key: &str| -> Result<[f32; 3], String> {
                let mut v = [0.; 3];
                for (i, x) in v.iter_mut().enumerate() {
                    *x = meta[key][i].as_f64().ok_or_else(invalid)? as f32;
                    if !x.is_finite() {
                        return Err(invalid());
                    }
                }
                Ok(v)
            };
            let start = meta["start"].as_f64().ok_or_else(invalid)? as f32;
            let end = meta["end"].as_f64().ok_or_else(invalid)? as f32;
            let texture = number(meta, "texture")?;
            if !start.is_finite()
                || !end.is_finite()
                || start >= end
                || texture > 2
                || (texture > 0 && uv.is_none())
            {
                return Err(invalid());
            }
            parts.push(KitchenPart {
                first,
                count,
                name: meta["name"].as_str().ok_or_else(invalid)?.into(),
                pivot: vector("pivot")?,
                offset: vector("offset")?,
                start,
                end,
                texture,
            });
        } else {
            parts.push(KitchenPart {
                first,
                count,
                name: String::new(),
                pivot: [0.; 3],
                offset: [0.; 3],
                start: 0.,
                end: 1.,
                texture: 0,
            });
        }
    }
    Ok(KitchenMesh { vertices, parts })
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn rejects_missing_or_invalid_glb() {
        for data in [&b""[..], &b"glTF"[..], &[0; 32][..]] {
            assert!(decode(data).is_err());
        }
    }
    #[test]
    fn normalized_gltf_colors_stay_linear_until_fragment_lighting() {
        // A small neutral/midtone fixture detects accidental display encoding in the loader.
        let mut data = vec![0_u8; 24]; // one position and one normal
        data.extend_from_slice(&[64, 128, 192, 255]);
        data.extend_from_slice(&[0; 8]); // three u16 indices and alignment
        let doc = serde_json::json!({
            "meshes": [{"primitives": [{"attributes": {"POSITION": 0, "NORMAL": 1, "COLOR_0": 2}, "indices": 3}]}],
            "bufferViews": [
                {"buffer": 0, "byteOffset": 0, "byteLength": 12},
                {"buffer": 0, "byteOffset": 12, "byteLength": 12},
                {"buffer": 0, "byteOffset": 24, "byteLength": 4},
                {"buffer": 0, "byteOffset": 28, "byteLength": 6}
            ],
            "accessors": [
                {"bufferView": 0, "componentType": 5126, "count": 1, "type": "VEC3"},
                {"bufferView": 1, "componentType": 5126, "count": 1, "type": "VEC3"},
                {"bufferView": 2, "componentType": 5121, "normalized": true, "count": 1, "type": "VEC4"},
                {"bufferView": 3, "componentType": 5123, "count": 3, "type": "SCALAR"}
            ]
        });
        let mut json = serde_json::to_vec(&doc).unwrap();
        while json.len() % 4 != 0 {
            json.push(b' ');
        }
        let mut bytes = b"glTF".to_vec();
        for v in [
            2,
            (28 + json.len() + data.len()) as u32,
            json.len() as u32,
            0x4e4f534a,
        ] {
            bytes.extend_from_slice(&v.to_le_bytes());
        }
        bytes.extend(json);
        bytes.extend_from_slice(&(data.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&0x004e4942_u32.to_le_bytes());
        bytes.extend(data);
        for vertex in decode(&bytes).unwrap().vertices.chunks_exact(12) {
            assert_eq!(&vertex[8..12], &[64. / 255., 128. / 255., 192. / 255., 1.]);
        }
    }
    #[test]
    fn delivered_kitchen_preserves_colors_and_fits_the_web_budget() {
        let bytes = include_bytes!("../../../assets/about/sams-kitchen-detailed.glb");
        let m = decode(bytes).unwrap();
        assert!(bytes.len() < 6_000_000);
        assert!(m.vertices.len() / 36 < 200_000);
        assert!(m.vertices.len() / 36 > 10_000);
        assert!(m.vertices.iter().all(|v| v.is_finite()));
        let names = m
            .parts
            .iter()
            .map(|p| p.name.as_str())
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(names.len(), 18);
        assert!(names.contains("ASM_17_Recipe_book") && names.contains("ASM_18_Laptop"));
        assert_eq!(m.parts.len(), 20);
        let mut cursor = 0;
        for p in &m.parts {
            assert_eq!(p.first, cursor);
            cursor += p.count;
            assert!(p.start >= 1. && p.end <= 144. && p.end > p.start);
            assert!(p.pivot.iter().chain(p.offset.iter()).all(|x| x.is_finite()));
            assert!(p.texture <= 2);
            if p.texture > 0 {
                let uv = m.vertices[p.first * 12..(p.first + p.count) * 12]
                    .chunks_exact(12)
                    .flat_map(|v| [v[6], v[7]])
                    .collect::<Vec<_>>();
                assert!(uv.iter().all(|v| (0.0..=1.0).contains(v)));
                assert!(uv.iter().any(|v| *v > 0.5));
            }
        }
        assert_eq!(cursor, m.vertices.len() / 12);
        assert_eq!(m.parts.iter().filter(|p| p.texture > 0).count(), 2);

        let colors = m
            .vertices
            .chunks_exact(12)
            .map(|v| [v[8].to_bits(), v[9].to_bits(), v[10].to_bits()])
            .collect::<std::collections::HashSet<_>>();
        assert!(
            colors.len() > 20,
            "The material palette must survive export"
        );
    }
}
